#include <cstdio>
#include <algorithm>
#include <vector>
#include <utility>

using namespace std;

int N, M, H, K;
typedef pair<int, int> cor_t; // height, vertStick index

struct knot_t {
    int col;
    int score;
    bool turned; // corresponding horizontal stick turning score
    knot_t* parallel;
    knot_t* next;
};

int scores[1005];
cor_t horizontalSticks[100007];
vector<knot_t> vertSticks[1005];

void init() {
    // Single scanf call for scores
    for (int i = 1; i <= N; i++) scanf("%d", &scores[i]);

    // Using a single scanf to read multiple values for horizontal sticks
    for (int i = 1; i <= M; i++) {
        scanf("%d %d", &horizontalSticks[i].second, &horizontalSticks[i].first);
        horizontalSticks[i].first = H - horizontalSticks[i].first;
    }

    // Reserve memory for vertical sticks in advance
    for (int i = 1; i <= N; i++) {
        vertSticks[i].clear();
        vertSticks[i].reserve(1005);
    }
}

void search(knot_t& a) {
    a.turned = true;
    auto nextptr = a.parallel->next;
    if (nextptr && !nextptr->turned) search(*nextptr);
}

int main() {
    while (scanf("%d%d%d%d", &N, &M, &H, &K) == 4 && N && M && H && K) {
        init();
        sort(horizontalSticks + 1, horizontalSticks + M + 1);

        for (int i = 1; i <= M; i++) {
            auto &cur = horizontalSticks[i];
            int leftIndex = cur.second, rightIndex = leftIndex + 1;
            auto &left = vertSticks[leftIndex], &right = vertSticks[rightIndex];
            int leftScore = left.empty() ? scores[leftIndex] : left.back().score,
                rightScore = right.empty() ? scores[rightIndex] : right.back().score;

            left.push_back({cur.second, rightScore, false, nullptr, left.empty() ? nullptr : &left.back()});
            right.push_back({cur.second + 1, leftScore, false, nullptr, right.empty() ? nullptr : &right.back()});

            left.back().parallel = &right.back();
            right.back().parallel = &left.back();
        }

        for (int i = 1; i <= K; i++) if (!vertSticks[i].empty()) search(vertSticks[i].back());

        int sum = 0;
        for (int i = 1; i <= K; i++) sum += vertSticks[i].empty() ? scores[i] : vertSticks[i].back().score;

        int diff = 0;
        for (int i = 1; i <= N; i++) {
            auto &curCol = vertSticks[i];
            for (auto &a : curCol) {
                auto &fst = a, &snd = *a.parallel;
                int fstCandidate = fst.next ? fst.next->score : scores[fst.col];
                int sndCandidate = snd.next ? snd.next->score : scores[snd.col];
                diff = min(diff, fst.turned * (fstCandidate - fst.score) + snd.turned * (sndCandidate - snd.score));
            }
        }

        printf("%d\n", sum + diff);
    }
    return 0;
}

